import { db } from "./db";

export interface GroupRow {
  id: number;
  name: string;
  invite_code: string;
  created_by: number;
  created_at: string;
}

export interface GroupWithStats extends GroupRow {
  member_count: number;
  track_count: number;
}

export interface GroupMember {
  user_id: number;
  name: string;
  joined_at: string;
  is_admin: boolean;
}

export function isMemberOfGroup(userId: number, groupId: number): boolean {
  const row = db
    .prepare(
      "SELECT 1 FROM group_members WHERE group_id = ? AND user_id = ?"
    )
    .get(groupId, userId);
  return row !== undefined;
}

export function isAdminOfGroup(userId: number, groupId: number): boolean {
  const row = db
    .prepare("SELECT 1 FROM groups WHERE id = ? AND created_by = ?")
    .get(groupId, userId);
  return row !== undefined;
}

/** Grupos a los que pertenece el usuario, con contadores. */
export function getUserGroups(userId: number): GroupWithStats[] {
  return db
    .prepare(
      `
      SELECT g.id, g.name, g.invite_code, g.created_by, g.created_at,
             (SELECT COUNT(*) FROM group_members gm WHERE gm.group_id = g.id) AS member_count,
             (SELECT COUNT(*) FROM tracks t WHERE t.group_id = g.id) AS track_count
      FROM groups g
      INNER JOIN group_members gm ON gm.group_id = g.id
      WHERE gm.user_id = ?
      ORDER BY g.created_at DESC, g.id DESC
      `
    )
    .all(userId) as unknown as GroupWithStats[];
}

export function getGroupById(groupId: number): GroupRow | null {
  const row = db.prepare("SELECT * FROM groups WHERE id = ?").get(groupId);
  return (row as GroupRow | undefined) ?? null;
}

export function getGroupByInviteCode(code: string): GroupRow | null {
  const row = db
    .prepare("SELECT * FROM groups WHERE UPPER(invite_code) = ?")
    .get(code);
  return (row as GroupRow | undefined) ?? null;
}

/**
 * Grupo + estado de membresía del usuario. Devuelve null si el grupo
 * no existe o el usuario no pertenece.
 */
export function getGroupForUser(
  groupId: number,
  userId: number
): (GroupWithStats & { is_admin: boolean }) | null {
  const group = getGroupById(groupId);
  if (!group) return null;
  if (!isMemberOfGroup(userId, groupId)) return null;

  const stats = db
    .prepare(
      `
      SELECT
        (SELECT COUNT(*) FROM group_members gm WHERE gm.group_id = ?) AS member_count,
        (SELECT COUNT(*) FROM tracks t WHERE t.group_id = ?) AS track_count
      `
    )
    .get(groupId, groupId) as { member_count: number; track_count: number };

  return {
    ...group,
    member_count: stats.member_count,
    track_count: stats.track_count,
    is_admin: group.created_by === userId,
  };
}

export function getGroupMembers(groupId: number): GroupMember[] {
  return db
    .prepare(
      `
      SELECT u.id AS user_id, u.name, gm.joined_at,
             CASE WHEN g.created_by = u.id THEN 1 ELSE 0 END AS is_admin
      FROM group_members gm
      INNER JOIN users u ON u.id = gm.user_id
      INNER JOIN groups g ON g.id = gm.group_id
      WHERE gm.group_id = ?
      ORDER BY is_admin DESC, u.name COLLATE NOCASE ASC
      `
    )
    .all(groupId) as unknown as GroupMember[];
}

import path from "node:path";
import { mkdirSync, statSync, unlinkSync } from "node:fs";
import { db } from "./db";

export const ALLOWED_EXTENSIONS = ["mp3", "wav", "ogg", "m4a"] as const;
export type AllowedExtension = (typeof ALLOWED_EXTENSIONS)[number];

const MIME_BY_EXT: Record<AllowedExtension, string[]> = {
  mp3: ["audio/mpeg", "audio/mp3"],
  wav: ["audio/wav", "audio/x-wav", "audio/wave", "audio/x-pn-wav"],
  ogg: ["audio/ogg", "application/ogg"],
  m4a: ["audio/mp4", "audio/x-m4a", "audio/mp4a-latm"],
};

export interface TrackRow {
  id: number;
  group_id: number;
  user_id: number;
  title: string;
  original_filename: string;
  stored_filename: string;
  mime_type: string;
  file_size: number;
  duration_seconds: number | null;
  status: string;
  created_at: string;
}

export function getMaxUploadBytes(): number {
  const raw = process.env.TEMAZO_MAX_UPLOAD_MB;
  const mb = raw ? Number(raw) : 50;
  const safe = Number.isFinite(mb) && mb > 0 ? mb : 50;
  return safe * 1024 * 1024;
}

export function getMaxUploadMb(): number {
  return Math.round(getMaxUploadBytes() / (1024 * 1024));
}

/** Directorio donde se guardan los archivos de audio. */
export function getUploadDir(): string {
  const dir = process.env.TEMAZO_UPLOAD_DIR ?? "uploads";
  return path.isAbsolute(dir) ? dir : path.join(process.cwd(), dir);
}

/** Devuelve la ruta absoluta segura de un archivo almacenado. */
export function getTrackFilePath(groupId: number, storedFilename: string): string {
  if (!/^[A-Za-z0-9._-]+$/.test(storedFilename)) {
    throw new Error("Nombre de archivo inválido.");
  }
  return path.join(getUploadDir(), String(groupId), storedFilename);
}

export function getTrackById(trackId: number): TrackRow | null {
  const row = db.prepare("SELECT * FROM tracks WHERE id = ?").get(trackId);
  return (row as TrackRow | undefined) ?? null;
}

export function extensionFromFilename(filename: string): string | null {
  const lower = filename.toLowerCase().split("?")[0];
  const dot = lower.lastIndexOf(".");
  if (dot === -1) return null;
  const ext = lower.slice(dot + 1);
  return ALLOWED_EXTENSIONS.includes(ext as AllowedExtension) ? ext : null;
}

export function isAllowedMimeForExt(ext: AllowedExtension, mime: string): boolean {
  return MIME_BY_EXT[ext].includes(mime.toLowerCase());
}

export interface InspectResult {
  ok: boolean;
  error?: string;
}

/** Valida los primeros bytes del archivo contra el formato declarado. */
export function inspectAudioMagic(buf: Buffer, ext: AllowedExtension): InspectResult {
  if (buf.length < 12) {
    return { ok: false, error: "El archivo parece estar vacío o corrupto." };
  }
  switch (ext) {
    case "mp3": {
      const hasId3 = buf.toString("latin1", 0, 3) === "ID3";
      const hasFrameSync = buf[0] === 0xff && (buf[1] & 0xe0) === 0xe0;
      if (!hasId3 && !hasFrameSync) {
        return { ok: false, error: "El archivo no parece un MP3 válido." };
      }
      break;
    }
    case "wav": {
      if (
        buf.toString("latin1", 0, 4) !== "RIFF" ||
        buf.toString("latin1", 8, 12) !== "WAVE"
      ) {
        return { ok: false, error: "El archivo no parece un WAV válido." };
      }
      break;
    }
    case "ogg": {
      if (buf.toString("latin1", 0, 4) !== "OggS") {
        return { ok: false, error: "El archivo no parece un OGG válido." };
      }
      break;
    }
    case "m4a": {
      if (buf.toString("latin1", 4, 8) !== "ftyp") {
        return { ok: false, error: "El archivo no parece un M4A válido." };
      }
      break;
    }
  }
  return { ok: true };
}

export function trackFileExists(groupId: number, storedFilename: string): boolean {
  try {
    statSync(getTrackFilePath(groupId, storedFilename)).isFile();
    return true;
  } catch {
    return false;
  }
}

/**
 * Crea el directorio de subidas del grupo (si no existe).
 * Devuelve la ruta absoluta del directorio.
 */
export function ensureGroupUploadDir(groupId: number): string {
  const dir = path.join(getUploadDir(), String(groupId));
  mkdirSync(dir, { recursive: true });
  return dir;
}

/** Elimina el archivo físico si existe (sin lanzar errores). */
export function deleteTrackFile(groupId: number, storedFilename: string): void {
  try {
    unlinkSync(getTrackFilePath(groupId, storedFilename));
  } catch {
    // el archivo ya no existe; ignorar
  }
}

import { db } from "./db";
import type { TrackRow } from "./tracks";

export interface TrackWithStats extends TrackRow {
  author_name: string;
  avg_score: number | null;
  vote_count: number;
  my_score: number | null;
  is_own: boolean;
}

export interface RankingEntry {
  position: number;
  track_id: number;
  title: string;
  author_name: string;
  avg_score: number | null;
  vote_count: number;
  created_at: string;
}

export function getMyScore(trackId: number, userId: number): number | null {
  const row = db
    .prepare("SELECT score FROM votes WHERE track_id = ? AND user_id = ?")
    .get(trackId, userId) as { score: number } | undefined;
  return row?.score ?? null;
}

export function getTrackStats(trackId: number): {
  avg_score: number | null;
  vote_count: number;
} {
  const row = db
    .prepare(
      "SELECT ROUND(AVG(score), 1) AS avg_score, COUNT(*) AS vote_count FROM votes WHERE track_id = ?"
    )
    .get(trackId) as { avg_score: number | null; vote_count: number };
  return { avg_score: row.avg_score, vote_count: row.vote_count };
}

/** Canciones de un grupo con datos de votación para el usuario actual. */
export function getTracksForGroup(
  groupId: number,
  currentUserId: number
): TrackWithStats[] {
  const rows = db
    .prepare(
      `
      SELECT t.*, u.name AS author_name,
             (SELECT ROUND(AVG(v.score), 1) FROM votes v WHERE v.track_id = t.id) AS avg_score,
             (SELECT COUNT(*) FROM votes v WHERE v.track_id = t.id) AS vote_count
      FROM tracks t
      INNER JOIN users u ON u.id = t.user_id
      WHERE t.group_id = ?
      ORDER BY t.created_at ASC, t.id ASC
      `
    )
    .all(groupId) as unknown as Omit<TrackWithStats, "my_score" | "is_own">[];

  const trackIds = rows.map((r) => r.id);
  const myScores = new Map<number, number>();
  if (trackIds.length > 0) {
    const placeholders = trackIds.map(() => "?").join(",");
    const voteRows = db
      .prepare(
        `SELECT track_id, score FROM votes WHERE user_id = ? AND track_id IN (${placeholders})`
      )
      .all(currentUserId, ...trackIds) as Array<{ track_id: number; score: number }>;
    for (const v of voteRows) myScores.set(v.track_id, v.score);
  }

  return rows.map((row) => ({
    ...row,
    my_score: myScores.get(row.id) ?? null,
    is_own: row.user_id === currentUserId,
  }));
}

/** Ranking del grupo: promedio desc, votos desc, publicación asc. */
export function getRanking(groupId: number): RankingEntry[] {
  const rows = db
    .prepare(
      `
      SELECT t.id AS track_id, t.title, t.created_at, u.name AS author_name,
             (SELECT ROUND(AVG(v.score), 1) FROM votes v WHERE v.track_id = t.id) AS avg_score,
             (SELECT COUNT(*) FROM votes v WHERE v.track_id = t.id) AS vote_count
      FROM tracks t
      INNER JOIN users u ON u.id = t.user_id
      WHERE t.group_id = ?
      ORDER BY avg_score DESC, vote_count DESC, t.created_at ASC, t.id ASC
      `
    )
    .all(groupId) as unknown as Array<{
    track_id: number;
    title: string;
    created_at: string;
    author_name: string;
    avg_score: number | null;
    vote_count: number;
  }>;

  return rows.map((row, index) => ({ position: index + 1, ...row }));
}

