  const ext = extensionFromFilename(file.name);
  if (!ext) return { error: "El formato de audio no está permitido. Usá MP3, WAV, OGG o M4A." };
  if (!isAllowedMimeForExt(ext, file.type)) return { error: "El formato de audio no está permitido." };
  const buf = Buffer.from(await file.arrayBuffer());
  const magic = inspectAudioMagic(buf, ext);
  if (!magic.ok) return { error: magic.error };

  // duration
  let duration: number | null = null;
  // write to a temp file first? We need track id before naming. So insert row first.
  let trackId: number;
  try {
    const result = db.prepare(`INSERT INTO tracks (...) VALUES (...)`).run(...);
    trackId = Number(result.lastInsertRowid);
  } catch (err) { log; return generic; }

  const storedFilename = `${trackId}.${ext}`;
  try {
    // compute duration (ffprobe needs the file on disk)
    ensureGroupUploadDir(groupId);
    const filePath = getTrackFilePath(groupId, storedFilename);
    writeFileSync(filePath, buf);
