    const probe = await probeWithFfmpeg(filePath);
    if (probe?.duration_seconds) duration = probe.duration_seconds;
    if (duration === null) duration = parseDuration(buf, ext);
    db.prepare("UPDATE tracks SET stored_filename=?, duration_seconds=?, status=? WHERE id=?")
      .run(storedFilename, duration, "ready", trackId);
  } catch (err) {
    console.error("[uploadTrack] file", err);
    db.prepare("DELETE FROM tracks WHERE id = ?").run(trackId);
    return { error: "No pudimos subir el archivo." };
  }

  revalidatePath(`/groups/${groupId}`);
  redirect(`/groups/${groupId}`);
}
