import { NextRequest, NextResponse } from "next/server";
import { statSync, createReadStream } from "node:fs";
import { Readable } from "node:stream";
import { getCurrentUser, verifySession, SESSION_COOKIE } from "@/lib/auth";
import { getTrackById, getTrackFilePath } from "@/lib/tracks";
import { isMemberOfGroup } from "@/lib/groups";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest, { params }: { params: Promise<{ trackId: string }> }) {
  const { trackId: rawId } = await params;
  const trackId = Number(rawId);
  const user = await getCurrentUser();
  if (!user) return new NextResponse("No autorizado", { status: 401 });
  const track = getTrackById(trackId);
  if (!track) return new NextResponse("No encontrado", { status: 404 });
  if (!isMemberOfGroup(user.id, track.group_id)) return new NextResponse("No autorizado", { status: 403 });
  // file
  let filePath;
  try { filePath = getTrackFilePath(track.group_id, track.stored_filename); } catch { 404 }
  let stat;
  try { stat = statSync(filePath); } catch { 404 }

  const range = req.headers.get("range");
  const size = stat.size;
  const headers: Record<string,string> = {
    "Content-Type": track.mime_type || "application/octet-stream",
    "Accept-Ranges": "bytes",
    "Content-Length": String(size),
  };

  if (range) {
    const match = /^bytes=(\d*)-(\d*)$/.exec(range);
    if (!match) return new NextResponse("Range inválido", { status: 416 });
    let start = match[1] ? parseInt(match[1]) : 0;
    let end = match[2] ? parseInt(match[2]) : size - 1;
    if (isNaN(start)) start = 0;
    if (isNaN(end) || end >= size) end = size - 1;
    if (start > end || start >= size) {
      return new NextResponse("Range fuera de rango", { status: 416, headers: { "Content-Range": `bytes */${size}` } });
    }
    const stream = createReadStream(filePath, { start, end });
    return new NextResponse(stream as any, {
      status: 206,
      headers: {
        ...headers,
        "Content-Length": String(end - start + 1),
        "Content-Range": `bytes ${start}-${end}/${size}`,
      },
    });
  }

  const stream = createReadStream(filePath);
  return new NextResponse(stream as any, { status: 200, headers });
}
```

Concern: Next.js route handlers streaming with createReadStream - NextResponse supports a ReadableStream body. node:fs createReadStream is a Node Readable stream; Next's Response accepts it? The Response constructor accepts a BodyInit. A Node Readable is a web ReadableStream with async iterator... Actually Next.js handles Node streams in Route Handlers by converting them. In practice, returning a Node stream from a route handler works in Next.js (it converts). But TypeScript typing: `new NextResponse(nodeStream)` - TS may complain. Use `Readable.toWeb(createReadStream(...))` from node:stream to make a web ReadableStream, which is clean and typed.

For large files, web streams might buffer? Readable.toWeb gives a proper web stream that doesn't buffer. Good.

Note about content-type for audio: browsers accept. For `audio/mpeg` etc fine.

