"use client";

import { useActionState, useState } from "react";
import { uploadTrack } from "@/actions/tracks";
import type { FormState } from "@/lib/result";

const initialState: FormState = {};

interface UploadTrackFormProps {
  groupId: number;
  maxUploadMb: number;
  allowedExts: string[];
  ffmpegOk: boolean;
}

export function UploadTrackForm({
  groupId,
  maxUploadMb,
  allowedExts,
  ffmpegOk,
}: UploadTrackFormProps) {
  const [state, formAction, pending] = useActionState(uploadTrack, initialState);
  const [clientError, setClientError] = useState<string | null>(null);

  function validateFile(file: File | null | undefined) {
    if (!file) return;
    const ext = file.name.split(".").pop()?.toLowerCase() ?? "";
    if (!allowedExts.includes(ext)) {
      setClientError(
        `El formato "${ext || "desconocido"}" no está permitido. Usá: ${allowedExts
          .map((e) => e.toUpperCase())
          .join(", ")}.`
      );
      return;
    }
    if (file.size > maxUploadMb * 1024 * 1024) {
      setClientError(
        `El archivo supera el tamaño máximo de ${maxUploadMb} MB.`
      );
      return;
    }
    setClientError(null);
  }

  return (
    <form action={formAction} className="space-y-4">
      <input type="hidden" name="groupId" value={groupId} />

      <div>
        <label htmlFor="title" className="label">
          Título de la canción
        </label>
        <input
          id="title"
          name="title"
          type="text"
          required
          maxLength={120}
          placeholder="Por ejemplo: La tormenta"
          className="input"
        />
      </div>

      <div>
        <label htmlFor="file" className="label">
          Archivo de audio
        </label>
        <input
          id="file"
          name="file"
          type="file"
          required
          accept={allowedExts.map((e) => `.${e}`).join(",")}
          onChange={(e) => validateFile(e.target.files?.[0])}
          className="block w-full text-sm text-neutral-400 file:mr-4 file:rounded-full file:border-0 file:bg-gradient-to-r file:from-violet-600 file:to-fuchsia-600 file:px-4 file:py-2 file:text-sm file:font-semibold file:text-white hover:file:from-violet-500 hover:file:to-fuchsia-500"
        />
        <p className="mt-2 text-xs text-neutral-500">
          Formatos: {allowedExts.map((e) => e.toUpperCase()).join(", ")}.
          Máximo {maxUploadMb} MB.
        </p>
      </div>

      {(clientError || state.error) && (
        <p className="rounded-xl border border-rose-500/30 bg-rose-500/10 px-4 py-2.5 text-sm text-rose-300">
          {clientError ?? state.error}
        </p>
      )}

      {!ffmpegOk && (
        <p className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-2.5 text-sm text-amber-200">
          FFmpeg no está instalado: la duración se calcula de forma
          aproximada y no se realiza el análisis completo del audio. La
          reproducción funciona igual.
        </p>
      )}

      <button type="submit" disabled={pending} className="btn-primary w-full">
        {pending ? "Subiendo…" : "Subir mi música"}
      </button>
    </form>
  );
}

