@import "tailwindcss";

@theme {
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue",
    Arial, sans-serif;
}

@layer base {
  html {
    @apply antialiased;
  }

  body {
    @apply bg-neutral-950 text-neutral-100;
  }

  audio {
    @apply w-full;
  }
}

/* Bases componibles (Tailwind v4 requiere @utility para poder usar @apply) */
@utility btn {
  @apply inline-flex items-center justify-center gap-2 rounded-full px-5 py-2.5 text-sm font-semibold transition
    focus:outline-none focus-visible:ring-2 focus-visible:ring-fuchsia-400 disabled:cursor-not-allowed
    disabled:opacity-50;
}

@layer components {
  .card {
    @apply rounded-2xl border border-white/10 bg-white/5 p-5 shadow-lg backdrop-blur-sm;
  }

  .btn-primary {
    @apply btn bg-gradient-to-r from-violet-600 to-fuchsia-600 text-white shadow-lg shadow-fuchsia-900/30
      hover:from-violet-500 hover:to-fuchsia-500 active:scale-[0.98];
  }

  .btn-ghost {
    @apply btn border border-white/15 bg-white/5 text-neutral-200 hover:bg-white/10 active:scale-[0.98];
  }

  .btn-danger {
    @apply btn border border-rose-500/30 bg-rose-500/10 text-rose-300 hover:bg-rose-500/20 active:scale-[0.98];
  }

  .input {
    @apply w-full rounded-xl border border-white/15 bg-white/5 px-4 py-2.5 text-neutral-100 placeholder:text-neutral-500
      focus:border-fuchsia-400 focus:outline-none focus:ring-2 focus:ring-fuchsia-500/30;
  }

  .label {
    @apply mb-1.5 block text-sm font-medium text-neutral-300;
  }
}

