import Link from "next/link";
import { getCurrentUser } from "@/lib/auth";
import { getUserGroups } from "@/lib/groups";
import { LoginForm } from "@/components/LoginForm";
import { CreateGroupForm } from "@/components/CreateGroupForm";
import { JoinGroupForm } from "@/components/JoinGroupForm";

function Hero() {
  return (
    <section className="py-8 text-center">
      <h1 className="text-5xl font-black tracking-tight text-transparent bg-gradient-to-r from-violet-400 via-fuchsia-400 to-amber-300 bg-clip-text sm:text-6xl">
        TEMAZO
      </h1>
      <p className="mx-auto mt-5 max-w-md text-lg text-neutral-300">
        Subí tu música. Escuchá la de los demás. Votá. Descubrí cuál es el{" "}
        <span className="font-semibold text-fuchsia-300">TEMAZO</span> del
        grupo.
      </p>
    </section>
  );
}

export default async function HomePage() {
  const user = await getCurrentUser();

  if (!user) {
    return (
      <div className="space-y-8">
        <Hero />
        <section className="card">
          <LoginForm />
        </section>
        <p className="text-center text-sm text-neutral-500">
          Sin contraseñas ni correos: elegís un nombre y listo.
        </p>
      </div>
    );
  }

  const groups = getUserGroups(user.id);

  return (
    <div className="space-y-10">
      <Hero />

      <section>
        <div className="mb-3 flex items-center justify-between">
          <h2 className="text-xl font-bold text-neutral-100">Mis grupos</h2>
          <Link href="/groups" className="text-sm font-medium text-fuchsia-300 hover:text-fuchsia-200">
            Ver todos
          </Link>
        </div>

        {groups.length === 0 ? (
          <p className="rounded-2xl border border-dashed border-white/15 px-5 py-6 text-center text-neutral-400">
            Todavía no pertenecés a ningún grupo. Creá uno o unite con un
            código para empezar.
          </p>
        ) : (
          <ul className="grid gap-3 sm:grid-cols-2">
            {groups.map((group) => (
              <li key={group.id}>
                <Link
                  href={`/groups/${group.id}`}
                  className="card block transition hover:border-fuchsia-400/40 hover:bg-white/10"
                >
                  <div className="flex items-center justify-between gap-3">
                    <span className="font-semibold text-neutral-100">
                      {group.name}
                    </span>
                    <span className="shrink-0 text-xs text-neutral-400">
                      {group.member_count} {group.member_count === 1 ? "integrante" : "integrantes"}
                    </span>
                  </div>
                  <p className="mt-1 text-sm text-neutral-500">{group.invite_code}</p>
                </Link>
              </li>
            ))}
          </ul>
        )}
      </section>

      <div className="grid gap-6 md:grid-cols-2">
        <section className="card">
          <h3 className="mb-3 text-lg font-bold text-neutral-100">Crear un grupo</h3>
          <CreateGroupForm />
        </section>
        <section className="card">
          <h3 className="mb-3 text-lg font-bold text-neutral-100">Unirme a un grupo</h3>
          <JoinGroupForm />
        </section>
      </div>
    </div>
  );
}

