import { useRef, useEffect } from "react";

export function AudioPlayer({ trackId }: { trackId: number }) {
  const ref = useRef<HTMLAudioElement>(null);
  const last = useRef(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onPlay = () => {
      const now = Date.now();
      if (now - last.current < 60_000) return;
      last.current = now;
      fetch(`/api/tracks/${trackId}/play`, { method: "POST", keepalive: true }).catch(() => {});
    };
    el.addEventListener("play", onPlay);
    return () => el.removeEventListener("play", onPlay);
  }, [trackId]);
  return <audio ref={ref} controls preload="metadata" controlsList="nodownload" className="w-full" src={`/api/tracks/${trackId}`} />;
}
