const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync("data/temazo.db");
console.log(
  "migraciones:",
  JSON.stringify(
    db.prepare("SELECT version,name FROM schema_migrations ORDER BY version").all()
  )
);
console.log(
  "columnas group_members:",
  JSON.stringify(
    db.prepare("PRAGMA table_info(group_members)").all().map((c) => c.name)
  )
);
console.log("--- miembros grupo 1 (COALESCE) ---");
console.log(
  JSON.stringify(
    db
      .prepare(
        `SELECT u.id AS user_id, COALESCE(gm.name, u.name) AS name, gm.name AS gm_name,
                CASE WHEN g.created_by = u.id THEN 1 ELSE 0 END AS is_admin
         FROM group_members gm
         INNER JOIN users u ON u.id = gm.user_id
         INNER JOIN groups g ON g.id = gm.group_id
         WHERE gm.group_id = ?
         ORDER BY is_admin DESC, name COLLATE NOCASE ASC`
      )
      .all(1)
  )
);
console.log("--- autores de tracks grupo 1 (COALESCE) ---");
console.log(
  JSON.stringify(
    db
      .prepare(
        `SELECT t.title, COALESCE(gm.name, u.name) AS author_name
         FROM tracks t
         INNER JOIN users u ON u.id = t.user_id
         LEFT JOIN group_members gm ON gm.group_id = t.group_id AND gm.user_id = t.user_id
         WHERE t.group_id = ?`
      )
      .all(1)
  )
);
db.close();

const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync("data/temazo.db");
const groupId = 1;
const name = "Miembro de Prueba";

const existing = db
  .prepare("SELECT id FROM users WHERE lower(name) = lower(?)")
  .get(name);
let memberId;
if (existing) {
  memberId = existing.id;
  console.log("usuario existente:", memberId);
} else {
  const r = db.prepare("INSERT INTO users (name) VALUES (?)").run(name);
  memberId = Number(r.lastInsertRowid);
  console.log("usuario creado:", memberId);
}
const already = db
  .prepare("SELECT 1 FROM group_members WHERE group_id = ? AND user_id = ?")
  .get(groupId, memberId);
console.log("ya era miembro:", already !== undefined);
if (!already) {
  db.prepare(
    "INSERT INTO group_members (group_id, user_id, name) VALUES (?, ?, ?)"
  ).run(groupId, memberId, name);
}
console.log(
  "miembros del grupo 1:",
  JSON.stringify(
    db
      .prepare(
        "SELECT u.id, COALESCE(gm.name, u.name) AS name FROM group_members gm INNER JOIN users u ON u.id=gm.user_id WHERE gm.group_id=1 ORDER BY gm.id"
      )
      .all()
  )
);

// rollback: quitar al miembro de prueba y su usuario
db.prepare("DELETE FROM group_members WHERE group_id=? AND user_id=?").run(
  groupId,
  memberId
);
db.prepare("DELETE FROM users WHERE id=?").run(memberId);
console.log("rollback ok");
db.close();

