import { db } from "./db.ts";

export interface TopTrack {
  track_id: number;
  title: string;
  group_id: number;
  group_name: string;
  author_name: string;
  avg_score: number | null;
  vote_count: number;
  play_count: number;
}

export interface Review {
  id: number;
  name: string;
  body: string;
  created_at: string;
}

/**
 * Canción destacada de toda la app: la mejor posicionada con el mismo
 * criterio que el ranking de grupo (promedio desc, votos desc, publicación
 * asc), entre grupos que no están ocultos del ranking.
 */
export function getGlobalTopTrack(): TopTrack | null {
  const row = db
    .prepare(
      `
      SELECT t.id AS track_id, t.title, t.group_id, g.name AS group_name,
             COALESCE(gm.name, u.name) AS author_name,
             (SELECT ROUND(AVG(v.score), 1) FROM votes v WHERE v.track_id = t.id) AS avg_score,
             (SELECT COUNT(*) FROM votes v WHERE v.track_id = t.id) AS vote_count,
             (SELECT COUNT(*) FROM plays p WHERE p.track_id = t.id) AS play_count
      FROM tracks t
      INNER JOIN groups g ON g.id = t.group_id
      INNER JOIN users u ON u.id = t.user_id
      LEFT JOIN group_members gm ON gm.group_id = t.group_id AND gm.user_id = t.user_id
      WHERE COALESCE(g.hidden_from_ranking, 0) = 0
        AND EXISTS (SELECT 1 FROM votes v WHERE v.track_id = t.id)
      ORDER BY avg_score DESC, vote_count DESC, t.created_at ASC, t.id ASC
      LIMIT 1
      `
    )
    .get() as unknown as TopTrack | undefined;

  return row ?? null;
}

/** Reseñas de una canción, de la más reciente a la más antigua. */
export function getReviews(trackId: number): Review[] {
  return db
    .prepare(
      "SELECT id, name, body, created_at FROM reviews WHERE track_id = ? ORDER BY created_at DESC, id DESC"
    )
    .all(trackId) as unknown as Review[];
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import type { FormState } from "@/lib/result";

const NAME_MAX = 60;
const BODY_MAX = 500;

export async function addReview(
  _prevState: FormState,
  formData: FormData
): Promise<FormState> {
  const trackId = Number(formData.get("trackId"));
  if (!Number.isInteger(trackId) || trackId <= 0) {
    return { error: "Canción inválida." };
  }

  const name = String(formData.get("name") ?? "").trim();
  if (!name) return { error: "Escribí tu nombre." };
  if (name.length > NAME_MAX) {
    return { error: `El nombre no puede superar los ${NAME_MAX} caracteres.` };
  }

  const body = String(formData.get("body") ?? "").trim();
  if (!body) return { error: "Escribí tu reseña." };
  if (body.length > BODY_MAX) {
    return { error: `La reseña no puede superar los ${BODY_MAX} caracteres.` };
  }

  try {
    const track = db
      .prepare(
        `
        SELECT t.id FROM tracks t
        INNER JOIN groups g ON g.id = t.group_id
        WHERE t.id = ? AND COALESCE(g.hidden_from_ranking, 0) = 0
        `
      )
      .get(trackId);
    if (!track) return { error: "Esa canción no está en el ranking." };

    db.prepare("INSERT INTO reviews (track_id, name, body) VALUES (?, ?, ?)").run(
      trackId,
      name,
      body
    );

    revalidatePath("/resenas");
    return { ok: true };
  } catch (err) {
    console.error("[addReview]", err);
    return { error: "No pudimos publicar tu reseña. Probá de nuevo." };
  }
}

"use client";

import { useActionState } from "react";
import { addReview } from "@/actions/reviews";
import type { FormState } from "@/lib/result";

const initialState: FormState = {};

export function AddReviewForm({ trackId }: { trackId: number }) {
  const [state, formAction, pending] = useActionState(addReview, initialState);

  return (
    <form
      action={formAction}
      className="rounded-2xl border border-white/10 bg-white/5 px-5 py-4"
    >
      <input type="hidden" name="trackId" value={trackId} />
      <p className="font-bold text-neutral-100">Dejá tu reseña</p>
      <div className="mt-3 space-y-3">
        <div>
          <label htmlFor="name" className="label">
            Tu nombre
          </label>
          <input
            id="name"
            name="name"
            type="text"
            required
            maxLength={60}
            placeholder="Por ejemplo: Nico"
            className="input max-w-xs"
          />
        </div>
        <div>
          <label htmlFor="body" className="label">
            ¿Qué opinás de esta canción?
          </label>
          <textarea
            id="body"
            name="body"
            required
            maxLength={500}
            rows={4}
            placeholder="Escribí tu reseña…"
            className="input"
          />
        </div>
      </div>
      {state.error && <p className="mt-2 text-sm text-rose-300">{state.error}</p>}
      <button type="submit" disabled={pending} className="btn-primary mt-3 w-full">
        {pending ? "Publicando…" : "Publicar reseña"}
      </button>
    </form>
  );
}

