          </p>
          <p className="text-neutral-300">
            🗳️ {top.vote_count} {top.vote_count === 1 ? "voto" : "votos"}
          </p>
          <p className="text-neutral-300">
            🎧 {top.play_count} {top.play_count === 1 ? "escucha" : "escuchas"}
