"use client";

import { useEffect, useRef } from "react";

const PLAY_DEBOUNCE_MS = 60_000;

export function AudioPlayer({ trackId }: { trackId: number }) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const lastPlayedAtRef = useRef(0);

  useEffect(() => {
    const el = audioRef.current;
    if (!el) return;

    const onPlay = () => {
      const now = Date.now();
      if (now - lastPlayedAtRef.current < PLAY_DEBOUNCE_MS) return;
      lastPlayedAtRef.current = now;
      fetch(`/api/tracks/${trackId}/play`, {
        method: "POST",
        keepalive: true,
      }).catch(() => {
        // si falla el registro, no interrumpir la reproducción
      });
    };

    el.addEventListener("play", onPlay);
    return () => el.removeEventListener("play", onPlay);
  }, [trackId]);

  return (
    <audio
      ref={audioRef}
      controls
      preload="metadata"
      controlsList="nodownload"
      className="w-full"
      src={`/api/tracks/${trackId}`}
    />
  );
}

