export function inspectVideoMagic(buf, ext): InspectResult {
  if (buf.length < 12) return {ok:false, error:"..."};
  switch(ext) {
    case "mp4":
    case "mov": {
      if (buf.toString("latin1",4,8) !== "ftyp") return {ok:false,error:"El archivo no parece un video MP4/MOV válido."};
      break;
    }
    case "webm": {
      if (buf.toString("latin1",0,4) !== "\x1A\x45\xDF\xA3") return {ok:false,error:"El archivo no parece un WebM válido."};
      break;
    }
  }
  return {ok:true};
}
