```tsx
"use client";
import { useEffect, useRef } from "react";

const PLAY_DEBOUNCE_MS = 60_000;

export function TrackPlayer({ trackId, isVideo }: { trackId: number; isVideo: boolean }) {
  const mediaRef = useRef<HTMLAudioElement | HTMLVideoElement>(null);
  const lastPlayedAtRef = useRef(0);

  useEffect(() => {
    const el = mediaRef.current;
    if (!el) return;
    const onPlay = () => { ... same ... };
    el.addEventListener("play", onPlay);
    return () => el.removeEventListener("play", onPlay);
  }, [trackId]);

  const src = `/api/tracks/${trackId}`;
  const common = { controls: true, preload: "metadata" as const, controlsList: "nodownload", className: "w-full", src };
  if (isVideo) {
    return <video ref={mediaRef as ...} {...common} />;
  }
  return <audio ref={mediaRef as ...} {...common} />;
}
```

TypeScript: useRef<HTMLMediaElement | null>(null). Then assigning to both audio/video refs — the ref types differ. A common approach: `const mediaRef = useRef<HTMLMediaElement | null>(null)` and pass `ref={mediaRef as React.RefObject<HTMLMediaElement>}`. Hmm, HTMLAudioElement and HTMLVideoElement both extend HTMLMediaElement. Passing `ref` typed for HTMLMediaElement to an `<audio>` element: React's ref for `<audio>` expects `Ref<HTMLAudioElement>`. A RefObject<HTMLMediaElement> isn't assignable directly. Use `ref={mediaRef as React.Ref<HTMLAudioElement>}` — a cast works. Actually simpler: separate refs? One ref used in either branch — but only one branch renders. I can use a single `useRef<HTMLMediaElement | null>(null)` and cast in JSX: `ref={(el) => { mediaRef.current = el; }}`. That callback avoids typing issues.

